package com.silverroom.camera;
import java.util.*;import android.opengl.GLES20;

/** Delayed frame/result ordering, failed GPU writes and persistent complete-frame presentation. */
public final class PreviewFramebufferProbe {
 static List<String> passed=new ArrayList<>();static void check(boolean yes,String name){if(!yes)throw new AssertionError(name);passed.add(name);}
 public static List<String> run(){
  PreviewFramebuffer buffer=new PreviewFramebuffer();check(!buffer.draw(300,400),"An empty framebuffer never presents uninitialized pixels");int copies=GLES20.copies;
  check(buffer.begin(300,400)&&GLES20.framebuffer!=0,"A logical candidate renders into an owned framebuffer instead of the window");GLES20.paint(101);check(buffer.commit()&&GLES20.framebuffer==0,"A complete candidate is committed only after returning to the original framebuffer");buffer.draw(300,400);check(GLES20.presented==101&&GLES20.copies==copies,"A complete logical frame is retained without glCopyTexSubImage2D");
  buffer.begin(300,400);GLES20.paint(0);buffer.abort();buffer.draw(300,400);check(GLES20.presented==101,"An aborted black/incomplete candidate cannot overwrite the last complete image");
  buffer.begin(300,400);GLES20.paint(202);GLES20.error=1282;check(!buffer.commit()&&buffer.problem().contains("1282"),"GPU render errors reject the candidate and retain diagnostic evidence");buffer.draw(300,400);check(GLES20.presented==101,"A rejected candidate continues to show the previous complete frame");
  GLES20.fboStatus=36054;check(!buffer.begin(300,400)&&GLES20.framebuffer==0,"Incomplete framebuffer allocation restores the window binding");buffer.draw(300,400);check(GLES20.presented==101,"Allocation failure leaves the displayed frame intact");GLES20.fboStatus=GLES20.GL_FRAMEBUFFER_COMPLETE;
  GLES20.copyError=1282;buffer.begin(300,400);GLES20.paint(303);buffer.commit();buffer.draw(300,400);check(GLES20.presented==303&&GLES20.copies==copies,"Logical preview works even when window-to-texture copying is unavailable");GLES20.copyError=0;
  int allocations=GLES20.allocations;for(int n=0;n<60;n++){buffer.begin(300,400);GLES20.paint(400+n);buffer.commit();buffer.draw(300,400);}check(GLES20.allocations<=allocations+1,"The two framebuffer textures are reused rather than reallocated per preview frame");
  for(int n=0;n<50;n++){GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT);buffer.draw(300,400);if(GLES20.presented!=459)throw new AssertionError("Black frame during delayed metadata");}check(GLES20.presented==459,"Long metadata gaps cannot reveal a cleared black window after a valid frame");
  GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,77);GLES20.glViewport(2,3,40,50);buffer.begin(300,400);buffer.abort();check(GLES20.framebuffer==77&&Arrays.equals(GLES20.viewport,new int[]{2,3,40,50}),"Abort restores the caller's framebuffer and viewport exactly");GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,0);GLES20.glViewport(0,0,300,400);
  GLES20.drawError=1282;check(!buffer.draw(300,400),"A failed GPU presentation is not falsely reported as a successful held frame");GLES20.drawError=0;check(buffer.draw(300,400)&&GLES20.presented==459,"A transient presentation error can retry the same complete frame");
  buffer.clear();check(!buffer.draw(300,400)&&!buffer.begin(0,400),"Pause/clear and invalid dimensions never revive a stale frame");
  PreviewLatch latch=new PreviewLatch();check(latch.drain(true,false,1,1000,false,false),"The first PRIVATE image is always drained before metadata to avoid producer stalls");latch.consumed(1,10,1000);check(!latch.drain(true,false,1,1030,false,false),"A consumed image waits briefly for its own result instead of being overwritten by newer images");
  check(!latch.drain(true,false,1,1200,true,false),"A proved image is drawn before consuming the next texture even if newer frames are queued");latch.displayed(1,10);check(latch.drain(true,false,1,1200,true,false),"Presentation acknowledgement releases the next pending image immediately");
  latch.consumed(1,11,1200);check(!latch.drain(true,false,1,1279,false,false)&&latch.drain(true,false,1,1280,false,false),"An 80ms result deadline keeps an unresponsive metadata path from blocking the producer indefinitely");
  check(latch.drain(true,false,1,1201,false,true),"A known rejected old-lens image is discarded without the metadata wait");check(latch.drain(true,true,1,1201,false,false),"Still capture continues draining PRIVATE buffers while JPEG output is in flight");
  check(latch.drain(false,false,1,1201,false,false)&&latch.drain(true,false,2,1201,false,false),"Stable routes and a new zoom epoch cannot inherit a previous image hold");latch.clear();check(latch.drain(true,false,1,1201,false,false),"Clearing preview state releases any old pending latch");
  LogicalZoomState state=new LogicalZoomState();state.reset(LogicalZoomProbe.bases());state.begin(85);LogicalZoomState.Tag current=state.tag(0);state.image(600);state.result(current,600L,"main",85/23f);check(state.rejected(600)&&state.proof()==null,"A mismatched physical result is remembered only as rejected, never as optical proof");state.begin(23);state.result(current,601L,"tele",85/23f);check(state.rejected(601),"Late requests of an earlier zoom epoch are identifiable without starving the next image");
  state.result(state.tag(0),602L,"main",1f);state.image(602);check(state.proof()!=null&&!state.rejected(602),"A valid exact pair remains the only way to admit a new frame");
  ZoomEngine engine=new ZoomEngine();engine.logicalPlan=new ZoomEngine.Plan();engine.logicalZoom.reset(LogicalZoomProbe.bases());engine.logicalZoom.begin(23);engine.previewReady=false;engine.frame=true;engine.texture.timestamp=700;engine.latchForUi();int consumed=engine.texture.updates;engine.frame=true;engine.texture.timestamp=701;engine.latchForUi();check(engine.texture.updates==consumed&&engine.frame,"Shipping latch preserves an unpaired current texture while keeping the newer frame pending");
  engine.logicalZoom.result(engine.logicalZoom.tag(0),700L,"main",1f);engine.latchForUi();check(engine.texture.updates==consumed,"Shipping latch does not skip the newly proved image when its callback requests a redraw");engine.previewLatch.displayed(engine.logicalZoom.epoch(),700);engine.latchForUi();check(engine.texture.updates==consumed+1&&engine.externalTimestamp==701,"Shipping latch advances only after the matched frame was presented");
  return passed;
 }
}
